# Contextual Relevancy Metric
# evaluates the retrieved context and checks whether it contains relevant information for answering the question.
# An irrelevant downgrade policy adds noise.
# Contextual Relevancy - Did the retriever return relevant information?
# It uses an LLM as a judge to evaluate the relationship between:
#  1. input — the question asked by the user.
#  2. actual_output — the answer generated by your RAG agent.
#  3. retrieval_context - the information your retriever found in the knowledge base 

import os
import pytest
import sys

from deepeval.test_case import LLMTestCase
from app.rag_agent import rag_support_agent_with_context

sys.path.insert(
    0,
    os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
)

@pytest.mark.parametrize("question", [
    "My subscription renews on the 31st. What happens in February?",
    "I cancelled my subscription. Can I still use the service, and can I get my money back?",
    "My card was declined. Will you automatically charge it again tomorrow?",
    "Does the Premium plan include unlimited users and priority support?",
    "What happens if I pause my subscription?"
])

def test_contextual_relevancy_agent_response(question, contextual_relevancy_metric):

    response = rag_support_agent_with_context(question)

    test_case = LLMTestCase(
        input = question,
        actual_output= response["answer"],
        retrieval_context= response["retrieval_context"]
    )

    metric = contextual_relevancy_metric
    metric.measure(test_case)

    print(
            f"Question: {question}\n"
            f"Metric score: {metric.score}\n"
            f"Metric reason: {metric.reason}\n"
            f"Agent Answer: {response['answer']}\n" 
            f"Retrived context: {response['retrieval_context']}"
        )
    
    for i, context in enumerate(response["retrieval_context"], start=1):
        print(f"\nDocument {i}:")
        print(context)
    
    assert metric.is_successful() , (
            f"Question: {question}\n"
            f"Score: {metric.score}\n"
            f"Reason: {metric.reason}\n"
            f"Answer: {response['answer']}"
        )

